    private GraphtyperBundle() { }
    static Runnable bounded(long millis,Runnable check){long start=System.nanoTime();return()->{check.run();if(Thread.currentThread().isInterrupted()||(System.nanoTime()-start)/1000000>millis)throw new IllegalStateException("GraphTyper total wall capacity/cancellation exceeded");};}
    private static Map<Path,String> roles(GraphtyperRequest.Spec s)throws IOException {
        var r=new LinkedHashMap<Path,String>();r.put(GraphtyperRuntime.absolute(s.value().get("reference")),"reference.fa");r.put(GraphtyperRuntime.absolute(s.value().get("reference_index")),"reference.fa.fai");int i=0;
        for(Object item:list(s.value().get("alignments"))){var a=object(item);String name=String.format(Locale.ROOT,"alignment-%05d.%s",i++,text(a.get("format")));r.put(GraphtyperRuntime.absolute(a.get("file")),name);r.put(GraphtyperRuntime.absolute(a.get("index")),name+(a.get("format").equals("bam")?".bai":".crai"));}
        if(s.value().get("variant_sites")!=null){r.put(GraphtyperRuntime.absolute(s.value().get("variant_sites")),"sites.vcf.gz");r.put(GraphtyperRuntime.absolute(s.value().get("variant_sites_index")),"sites.vcf.gz.tbi");}return r;
    }
    private static Map<String,Object> effective(GraphtyperRequest.Spec s)throws IOException {var files=new ArrayList<String>();int i=0;for(Object raw:list(s.value().get("alignments")))files.add(String.format(Locale.ROOT,"alignment-%05d.%s",i++,text(object(raw).get("format"))));return map("alignment_files",files);}
    private static Pin jsonPin(Object v)throws IOException {byte[] raw=(NextflowJson.json(v)+"\n").getBytes(StandardCharsets.UTF_8);return new Pin(raw.length,sha(raw));}
    private static void prepare(Path root,GraphtyperRequest.Spec s,byte[] raw,Object inputs,Object sources,Object binding,Object runtime)throws IOException {
        Files.write(root.resolve("request.json"),raw,StandardOpenOption.CREATE_NEW);writeJson(root.resolve("captured-inputs.json"),inputs);writeJson(root.resolve("source-inputs.json"),sources);writeJson(root.resolve("runtime-binding.json"),binding);writeJson(root.resolve("runtime.json"),runtime);Files.writeString(root.resolve("WARNINGS.md"),GraphtyperRuntime.ACTION+"\n\n"+warnings(),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);Path engine=Files.createDirectory(root.resolve("engine"));Files.createDirectory(engine.resolve("inputs"));Files.write(engine.resolve("worker.py"),GraphtyperRuntime.resource("worker.py"),StandardOpenOption.CREATE_NEW);writeJson(engine.resolve("effective.json"),effective(s));writeJson(engine.resolve("profile.json"),GraphtyperRuntime.profile(s.profile()));
    }
    private static Map<Path,Pin> anchors(Path root,GraphtyperRequest.Spec s,byte[] raw,Object inputs,Object sources,Object binding,Object runtime)throws IOException {
        var r=new HashMap<Path,Pin>();r.put(GraphtyperRuntime.producerPath(),GraphtyperRuntime.producer());r.put(root.resolve("request.json"),new Pin(raw.length,sha(raw)));for(var row:Map.of("captured-inputs.json",inputs,"source-inputs.json",sources,"runtime-binding.json",binding,"runtime.json",runtime,"engine/effective.json",effective(s),"engine/profile.json",GraphtyperRuntime.profile(s.profile())).entrySet())r.put(root.resolve(row.getKey()),jsonPin(row.getValue()));byte[] worker=GraphtyperRuntime.resource("worker.py");r.put(root.resolve("engine/worker.py"),new Pin(worker.length,sha(worker)));return r;
    }
    static Path capture(Path request,Path supplied,Runnable cancellation)throws IOException {
        GraphtyperRuntime.platform();if(!Files.isReadable(request))throw new GraphtyperRuntime.Unavailable("GraphTyper request unavailable: "+request);byte[] raw=bytes(request,16777216);var s=GraphtyperRequest.parse(SimpleJson.parse(utf8(raw)));Runnable check=bounded(s.wallMillis(),cancellation);Pin producer=GraphtyperRuntime.producer();var runtime=GraphtyperRuntime.open(s.runtime(),s.profile(),check);var roles=roles(s);var inputs=new TreeMap<String,Object>();var sources=new ArrayList<Object>();long total=0;
        for(var row:roles.entrySet()){Path p=row.getKey();if(!Files.isRegularFile(p)||!Files.isReadable(p))throw new GraphtyperRuntime.Unavailable("Complete permitted original input unavailable: "+p);Pin pin=pin(p,s.inputBytes(),check);total=Math.addExact(total,pin.bytes());require(total<=s.inputBytes(),"Complete input byte capacity exceeded");inputs.put(row.getValue(),map("kind","file","mode",mode(p),"bytes",pin.bytes(),"sha256",pin.sha256()));sources.add(map("original",p.toString(),"captured",row.getValue(),"bytes",pin.bytes(),"sha256",pin.sha256()));}
        Path root=GraphtyperRuntime.newRoot(supplied);require(root.toString().matches("/[A-Za-z0-9_./-]+"),"NEW literal capture directory without shell metacharacters or whitespace required for source legacy scripts");runtime.separate(root);for(Path p:roles.keySet())require(!p.startsWith(root)&&!root.startsWith(p),"Capture overlaps original input");Files.createDirectory(root);Object binding=map("path",runtime.root().toString(),"seal",runtime.seal());
        try{
            prepare(root,s,raw,inputs,sources,binding,runtime.value());for(var row:roles.entrySet()){Path p=root.resolve("engine/inputs").resolve(row.getValue());Files.copy(row.getKey(),p,StandardCopyOption.COPY_ATTRIBUTES);require(pin(p,s.inputBytes(),check).equals(fingerprint(inputs.get(row.getValue()),s.inputBytes())),"Captured input bytes differ");}
            runtime=runtime.anchored(anchors(root,s,raw,inputs,sources,binding,runtime.value()));runtime=execute(root,s,runtime,inputs,check);for(var row:roles.entrySet())require(pin(row.getKey(),s.inputBytes(),check).equals(fingerprint(inputs.get(row.getValue()),s.inputBytes())),"Original input changed during calling");require(Arrays.equals(raw,bytes(request,16777216)),"Original request changed during calling");finish(root,s,runtime,inputs,producer,check);return root;
        }catch(IOException|RuntimeException|Error e){failure(root,e);throw e;}
    }
    private static void immutable(Path root,GraphtyperRequest.Spec s,GraphtyperRuntime.Context runtime,Object inputs,Runnable check)throws IOException {runtime.verify(check);require(NextflowJson.json(inputs).equals(NextflowJson.json(manifest(tree(root.resolve("engine/inputs"),s.files(),s.inputBytes(),s.inputBytes(),check)))),"Complete captured input population changed");}
    private record NativeInput(Object report,GraphtyperAlignmentAudit.Reference reference) { }
