        var programs=object(runtime.value().get("programs"));List<String> command=List.of(text(programs.get("python")),"-I","-S","-B",root.resolve("engine/worker.py").toString(),root.toString());writeJson(root.resolve("CALL-COMMAND.json"),command);NextflowProcess.executeSession(command,runtime.environment(),root.resolve("process-call"),root,root,s.process(),()->immutable(root,s,selected,inputs,check),check);immutable(root,s,runtime,inputs,check);
        var declaration=object(json(root.resolve("engine/OUTPUTS.json"),134217728));require(declaration.get("status").equals("ORIGINAL_GRAPH_CALLER_EXIT_SUCCESS_PROVISIONAL_ONLY")&&Boolean.FALSE.equals(declaration.get("analysis_admitted")),"Original complete final output declaration absent");var rows=new ArrayList<Object>();var warnings=new ArrayList<String>();var found=new HashSet<String>();Path tables=Files.createDirectory(root.resolve("vcf-records"));var c=s.capacity();
        var limits=new GraphtyperVcfAudit.Limits(integer(c.get("vcf_decoded_bytes"),1,1000000000000L),integer(c.get("vcf_records"),1,1000000000000L),integer(c.get("genotype_cells"),1,1000000000000L),(int)integer(c.get("line_characters"),256,16777216),(int)integer(c.get("vcf_header_lines"),1,1000000),s.samples().size(),(int)integer(c.get("vcf_alleles"),1,1000000));long records=0,cells=0,decoded=0;int ordinal=0;
